// Change this value to report on a different campaign.
const CAMPAIGN_ID = 'cle-synthetic-demo';
const rows = $input.all().map(x => x.json);
const campaignRows = rows.filter(r => String(r.campaign_id) === CAMPAIGN_ID);
const variants = ['A','B'];
const unique = (items) => new Set(items.map(r => String(r.prospect_id)).filter(Boolean));
const intersectionSize = (left, right) => [...left].filter(id => right.has(id)).length;
const result = variants.map(variant => {
  const v = campaignRows.filter(r => String(r.variant) === variant);
  const idsFor = type => unique(v.filter(r => r.event_type === type));
  const deliveredIds = idsFor('delivered');
  const repliedIds = idsFor('replied');
  const qualifiedIds = idsFor('qualified');
  const meetingIds = idsFor('meeting_booked');
  const replies = intersectionSize(deliveredIds, repliedIds);
  const qualified = [...deliveredIds].filter(id => repliedIds.has(id) && qualifiedIds.has(id)).length;
  const meetings = intersectionSize(deliveredIds, meetingIds);
  const delivered = deliveredIds.size;
  return {
    variant,
    events: v.length,
    delivered,
    replies,
    qualified_replies: qualified,
    meetings_booked: meetings,
    reply_rate: delivered ? replies / delivered : null,
    qualified_reply_rate: delivered ? qualified / delivered : null,
    meeting_rate: delivered ? meetings / delivered : null,
    rate_basis: 'unique_delivered_prospects',
    interpretation: delivered < 10 ? 'directional_only_small_sample' : 'review_context_before_inference'
  };
});
return [{json:{campaign_learning_engine:true,campaign_id:CAMPAIGN_ID,mode:'demo_only',send_enabled:false,events_included:campaignRows.length,variants:result}}];
